window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bc56d7db5d45285c"]={"versions": [{"id": "FIG-bc56d7db5d45285c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Rahmenformatdiagramm (Bit-/Byte-Struktur) für das Vehicle Data Provider (VDP) Nachrichtenformat innerhalb der AUTOSAR Foundation / Adaptive Platform. Das Diagramm spezifiziert die oberste Gliederung einer VDP-Nachricht zur strukturierten Übertragung von Fahrzeugdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Nachrichtengliederung umfasst zwei unmittelbar aufeinanderfolgende logische Blöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Header</strong>: Gelblich hinterlegtes Präfixfeld zur Aufnahme von Metadaten und Steuerinformationen des Protokolls.</li>\n<li><strong>Payload</strong>: Grünlich hinterlegtes Nutzdatenfeld variabler bzw. nachgelagerter Länge zur Aufnahme der eigentlichen Fahrzeug- und Sensordateninhalte.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Lineare Serialisierungsreihenfolge bei der Übertragung und Deserialisierung:</p>\n<ol class=\"fig-list\">\n<li>Zuerst wird der <code>Header</code> übertragen bzw. ausgewertet, um Kontext und Struktur der nachfolgenden Daten festzustellen.</li>\n<li>Unmittelbar folgend wird die <code>Payload</code> übertragen und den entsprechenden Zielanwendungen oder Verarbeitungsinstanzen zugeführt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Rahmendefinition für die Kapselung von VDP-Nachrichten. Entwickler müssen sicherstellen, dass jede VDP-Nachricht mit dem definierten Header beginnt, bevor Nutzdaten (Payload) verarbeitet oder angehängt werden. Parser müssen die strikte Trennung von Header- und Nutzdatenbereich einhalten.</p>"}, {"id": "FIG-3a9dc92813102892", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Rahmenformatdiagramm (Bit-/Byte-Struktur) für das Vehicle Data Provider (VDP) Nachrichtenformat innerhalb der AUTOSAR Foundation / Adaptive Platform. Das Diagramm spezifiziert die oberste Gliederung einer VDP-Nachricht zur strukturierten Übertragung von Fahrzeugdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Nachrichtengliederung umfasst zwei unmittelbar aufeinanderfolgende logische Blöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Header</strong>: Gelblich hinterlegtes Präfixfeld zur Aufnahme von Metadaten und Steuerinformationen des Protokolls.</li>\n<li><strong>Payload</strong>: Grünlich hinterlegtes Nutzdatenfeld variabler bzw. nachgelagerter Länge zur Aufnahme der eigentlichen Fahrzeug- und Sensordateninhalte.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Lineare Serialisierungsreihenfolge bei der Übertragung und Deserialisierung:</p>\n<ol class=\"fig-list\">\n<li>Zuerst wird der <code>Header</code> übertragen bzw. ausgewertet, um Kontext und Struktur der nachfolgenden Daten festzustellen.</li>\n<li>Unmittelbar folgend wird die <code>Payload</code> übertragen und den entsprechenden Zielanwendungen oder Verarbeitungsinstanzen zugeführt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Rahmendefinition für die Kapselung von VDP-Nachrichten. Entwickler müssen sicherstellen, dass jede VDP-Nachricht mit dem definierten Header beginnt, bevor Nutzdaten (Payload) verarbeitet oder angehängt werden. Parser müssen die strikte Trennung von Header- und Nutzdatenbereich einhalten.</p>"}], "trans": [{"from": "FIG-bc56d7db5d45285c", "to": "FIG-3a9dc92813102892", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
